import React, { useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import './styles.css';

type Row = Record<string, any>;
type Modal = { kind: string; item?: Row; token?: string } | null;
type Field = { name: string; label: string; type?: string; required?: boolean; value?: string | number; options?: { value: string; label: string }[]; min?: string; step?: string };
const money = (c: number = 0) => new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD' }).format(c / 100);
const date = (s: string | null) => s ? new Date(s.length === 10 ? s + 'T12:00:00' : s).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : 'No due date';
const label = (s: string) => ({ todo: 'Todo', in_progress: 'In progress', read_only: 'Read only' }[s] || s.charAt(0).toUpperCase() + s.slice(1));
const initials = (s: string = '') => s.split(' ').filter(Boolean).slice(0, 2).map(p => p[0]).join('').toUpperCase();
const statuses = (values: string[]) => values.map(v => ({ value: v, label: label(v) }));
const names = ['Overview', 'Customers', 'Inventory', 'Orders', 'Invoices', 'Projects', 'Activity', 'Team'];
const paths: Record<string, string> = {
  Overview: 'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',
  Customers: 'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87',
  Inventory: 'm12 3 9 5v9l-9 5-9-5V8z M3 8l9 5 9-5 M12 13v9 M7.5 5.5l9 5',
  Orders: 'M7 3H3v4 M3 3l4 4 M7 7h13l-2 9H8L6 5 M9 21h.01 M17 21h.01',
  Invoices: 'M6 3h12v19l-3-2-3 2-3-2-3 2z M9 7h6 M9 11h6 M9 15h3',
  Projects: 'M3 5h7l2 2h9v14H3z M7 12h4 M7 16h7',
  Activity: 'M3 12h4l3-8 4 16 3-8h4',
  Team: 'M12 3 3 7v5c0 5 9 10 9 10s9-5 9-10V7z M8 12l3 3 5-6',
  plus: 'M12 5v14 M5 12h14', search: 'M21 21l-5-5 M10 18a8 8 0 1 0 0-16 8 8 0 0 0 0 16',
  arrow: 'M5 12h14 M13 6l6 6-6 6', down: 'M12 3v12 M7 10l5 5 5-5 M5 17v4h14v-4',
  edit: 'm16 3 5 5-12 12H4v-5z M13 6l5 5', trash: 'M3 6h18 M9 6V3h6v3 M5 6l1 15h12l1-15 M10 10v7 M14 10v7',
  close: 'M6 6l12 12 M18 6 6 18', menu: 'M3 6h18 M3 12h18 M3 18h18', logout: 'M9 4H4v16h5 M13 12h8 M17 8l4 4-4 4',
  check: 'M5 12l4 4L19 6', clock: 'M12 8v5l3 2 M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',
  file: 'M14 2H4v20h16V8z M14 2v6h6 M8 13h8 M8 17h5', stock: 'M12 19V5 M6 11l6-6 6 6',
};
function Icon({ name, size = 20 }: { name: string; size?: number }) { return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={paths[name] || paths.file}/></svg>; }
function Brand() { return <div className="brand"><span className="brand-mark"><svg viewBox="0 0 28 28" aria-hidden="true"><path d="M5 5h18v5H10v4h10v5H10v6H5z" fill="currentColor"/><path d="m18 21 5-5v9h-5z" fill="currentColor" opacity=".55"/></svg></span><span>foundry<span className="brand-dot">.</span></span></div>; }
function Badge({ value }: { value: string }) { return <span className={`badge ${value}`}>{label(value)}</span>; }
function Empty({ icon, title, children }: { icon: string; title: string; children?: React.ReactNode }) { return <div className="empty"><span className="empty-icon"><Icon name={icon} size={28}/></span><h3>{title}</h3><p>{children || 'Your workspace is ready. Add your first record to get started.'}</p></div>; }
function Form({ fields, submit, onSubmit, busy, children }: { fields: Field[]; submit: string; onSubmit: (data: Row) => void; busy: boolean; children?: React.ReactNode }) {
  return <form onSubmit={e => { e.preventDefault(); onSubmit(Object.fromEntries(new FormData(e.currentTarget))); }} className="form">
    {fields.map(f => <label key={f.name} className={f.type === 'textarea' ? 'wide' : ''}>{f.label}{f.required && <span className="required" aria-hidden="true"> *</span>}
      {f.options ? <select aria-label={f.label} name={f.name} defaultValue={f.value ?? ''} required={f.required}>{f.options.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}</select> : f.type === 'textarea' ? <textarea aria-label={f.label} name={f.name} defaultValue={f.value} rows={3} required={f.required}/> : <input aria-label={f.label} name={f.name} type={f.type || 'text'} defaultValue={f.value} required={f.required} min={f.min} step={f.step} autoComplete={f.name === 'password' ? 'new-password' : 'off'}/>}
    </label>)}{children}<div className="form-footer"><span className="muted small">Changes are saved to this workspace.</span><button className="button primary" disabled={busy}>{busy ? 'Saving...' : submit}<Icon name="arrow" size={16}/></button></div>
  </form>;
}
function Dialog({ name, close, children, error }: { name: string; close: () => void; children: React.ReactNode; error: string }) {
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => { const d = ref.current!; const previous = document.activeElement as HTMLElement; d.showModal(); return () => { d.close(); previous?.focus(); }; }, []);
  return <dialog ref={ref} aria-label={name} onCancel={e => { e.preventDefault(); close(); }} onClick={e => { if (e.target === ref.current) close(); }}><div className="dialog-head"><div><span className="eyebrow">FOUNDRY WORKSPACE</span><h2>{name}</h2></div><button className="icon-button" aria-label="Close dialog" onClick={close}><Icon name="close"/></button></div><div className="dialog-body">{error && <div role="alert" className="alert">{error}</div>}{children}</div></dialog>;
}

async function request(path: string, method = 'GET', body?: any) {
  const res = await fetch(path, { method, headers: body instanceof FormData ? undefined : body === undefined ? undefined : { 'Content-Type': 'application/json' }, body: body === undefined ? undefined : body instanceof FormData ? body : JSON.stringify(body) });
  const data = res.status === 204 ? null : await res.json();
  if (!res.ok) throw Object.assign(new Error(data?.error?.message || 'Something went wrong.'), { status: res.status });
  return data;
}

function App() {
  const [me, setMe] = useState<Row | null>(null), [authLoading, setAuthLoading] = useState(true);
  const [route, setRoute] = useState(location.pathname), [data, setData] = useState<Row>({}), [loading, setLoading] = useState(false);
  const [modal, setModal] = useState<Modal>(null), [error, setError] = useState(''), [notice, setNotice] = useState(''), [busy, setBusy] = useState(false);
  const [mobile, setMobile] = useState(false), [search, setSearch] = useState(''), [status, setStatus] = useState(''), [priority, setPriority] = useState('');
  const [projectId, setProjectId] = useState<string | null>(null), [version, setVersion] = useState(0);
  const revision = useRef(-1), generation = useRef(0);
  const workspace = me?.workspaces?.find((w: Row) => w.id === me.activeWorkspaceId) || me?.workspaces?.[0];
  const wid = workspace?.id, role = workspace?.role;
  const write = !!role && role !== 'read_only', ops = ['owner', 'manager'].includes(role), owner = role === 'owner';
  const page = route === '/join' ? 'Join workspace' : names.find(n => route.startsWith('/' + n.toLowerCase())) || 'Overview';
  function navigate(path: string) { history.pushState({}, '', path); setRoute(path); setSearch(''); setStatus(''); setPriority(''); setProjectId(null); setMobile(false); setError(''); }
  async function auth() {
    try { const info = await request('/api/auth/me'); setMe(info); return info; } catch (e: any) { if (e.status === 401) setMe(null); else setError(e.message); } finally { setAuthLoading(false); }
  }
  async function refresh(w: string) {
    const gen = ++generation.current;
    const info = await request('/api/auth/me');
    if (gen !== generation.current) return;
    setMe(info);
    if (!info.workspaces.some((m: Row) => m.id === w)) { setData({}); return; }
    const keys = ['summary', 'customers', 'products', 'orders', 'invoices', 'projects', 'tasks', 'activity', 'members'];
    const result = await Promise.all(keys.map(k => request(`/api/w/${w}/${k}`)));
    if (gen !== generation.current) return;
    setData(Object.assign({}, ...result.map((r, i) => keys[i] === 'summary' ? { summary: r } : r)));
    setVersion(v => v + 1); setLoading(false);
  }
  useEffect(() => { auth(); const pop = () => { setRoute(location.pathname); setSearch(''); setStatus(''); }; window.addEventListener('popstate', pop); return () => window.removeEventListener('popstate', pop); }, []);
  useEffect(() => {
    if (!wid) return;
    let alive = true, running = false;
    setData({}); setLoading(true); setModal(null); revision.current = -1;
    const poll = async () => {
      if (running || !alive) return; running = true;
      try {
        const sync = await request(`/api/w/${wid}/sync`);
        if (!alive) return;
        if (sync.revision !== revision.current) { await refresh(wid); if (alive) revision.current = sync.revision; }
      } catch (e: any) { if (alive) { if ([401, 404].includes(e.status)) { await auth(); setModal(null); } else setError(e.message); setLoading(false); } }
      finally { running = false; }
    };
    poll(); const timer = setInterval(poll, 1000);
    return () => { alive = false; generation.current++; clearInterval(timer); };
  }, [wid]);
  useEffect(() => { if (!notice) return; const timer = setTimeout(() => setNotice(''), 4000); return () => clearTimeout(timer); }, [notice]);
  useEffect(() => { setModal(null); setError(''); }, [role]);
  const api = (path: string, method = 'GET', body?: any) => request(`/api/w/${wid}${path}`, method, body);
  const open = (kind: string, item?: Row) => { setError(''); setModal({ kind, item }); };
  const close = () => { if (!busy) { setModal(null); setError(''); } };
  async function action(fn: () => Promise<any>, success: string, keep = false) {
    setBusy(true); setError('');
    try { const result = await fn(); if (wid) await refresh(wid); if (!keep) setModal(null); setNotice(success); return result; }
    catch (e: any) { if (e.status === 401) { await auth(); setModal(null); } else setError(e.message); } finally { setBusy(false); }
  }
  const remove = (type: string, item: Row) => { if (confirm(`Delete ${item.name || item.title || item.number || 'this record'}? This cannot be undone.`)) action(() => api(`/${type}/${item.id}`, 'DELETE'), 'Record deleted.'); };
  const lookup = (type: string, rid: string) => (data[type] || []).find((r: Row) => r.id === rid);
  const customerName = (rid: string) => lookup('customers', rid)?.name || 'Customer';
  const exportLink = (type: string) => <a className="button secondary" href={`/api/w/${wid}/export.csv?type=${type}`}><Icon name="down" size={16}/>Export {type}</a>;
  const addButton = (name: string, kind: string) => <button className="button primary" onClick={() => open(kind)}><Icon name="plus" size={17}/>{name}</button>;
  const searchBox = (name: string) => <label className="search"><Icon name="search" size={18}/><input aria-label={name} placeholder={name + '...'} value={search} onChange={e => setSearch(e.target.value)}/>{search && <button aria-label="Clear search" onClick={() => setSearch('')}><Icon name="close" size={15}/></button>}</label>;
  function rowActions(type: string, r: Row, title: string, canEdit = write) { return <div className="row-actions"><button className="text-button" aria-label={`Open ${type} ${title}`} onClick={() => open(`${type}-details`, r)}>View<Icon name="arrow" size={14}/></button>{canEdit && <><button className="icon-button" aria-label={`Edit ${type} ${title}`} onClick={() => open(`edit-${type}`, r)}><Icon name="edit" size={16}/></button><button className="icon-button danger" aria-label={`Delete ${type} ${title}`} onClick={() => remove(type === 'customer' ? 'customers' : type === 'project' ? 'projects' : 'tasks', r)}><Icon name="trash" size={16}/></button></>}</div>; }
  const summary = data.summary || {};
  const customerFields = (c?: Row): Field[] => [{ name: 'name', label: 'Name', required: true, value: c?.name }, { name: 'email', label: 'Email', type: 'email', value: c?.email }, { name: 'company', label: 'Company', value: c?.company }, { name: 'notes', label: 'Notes', type: 'textarea', value: c?.notes }];
  const productFields = (p?: Row): Field[] => [{ name: 'sku', label: 'SKU', required: true, value: p?.sku }, { name: 'name', label: 'Product name', required: true, value: p?.name }, { name: 'description', label: 'Description', type: 'textarea', value: p?.description }, { name: 'price', label: 'Unit price (USD)', type: 'text', required: true, value: p ? (p.priceCents / 100).toFixed(2) : '' }];
  const taskFields = (t?: Row): Field[] => [{ name: 'title', label: 'Title', required: true, value: t?.title }, { name: 'description', label: 'Description', type: 'textarea', value: t?.description }, { name: 'status', label: 'Status', options: statuses(['todo', 'in_progress', 'done']), value: t?.status || 'todo' }, { name: 'priority', label: 'Priority', options: statuses(['low', 'medium', 'high']), value: t?.priority || 'medium' }, { name: 'assigneeId', label: 'Assignee', options: [{ value: '', label: 'Unassigned' }, ...(data.members || []).map((m: Row) => ({ value: m.userId, label: m.name }))], value: t?.assigneeId || '' }, { name: 'dueDate', label: 'Due date', type: 'date', value: t?.dueDate || '' }];

  if (authLoading) return <div className="boot"><Brand/><span>Opening your workspace...</span></div>;
  if (!me) {
    const signup = route === '/signup';
    return <div className="auth-shell"><aside className="auth-story"><Brand/><div className="story-copy"><div className="eyebrow">LESS FRICTION. MORE FORWARD.</div><h1>Good work.<br/>Great together.</h1><p>Your customers, commerce, and projects.<br/>One workspace to keep it all moving.</p><div className="story-graphic"><div className="orbit o1"/><div className="orbit o2"/><div className="orbit o3"/><div className="graphic-tile t1"><Icon name="Customers"/>Relationships</div><div className="graphic-tile t2"><Icon name="Inventory"/>Operations</div><div className="graphic-tile t3"><Icon name="Projects"/>Delivery</div><div className="graphic-center"><Brand/></div></div></div><span className="auth-bottom">A little more connected. A lot more possible.</span></aside><main className="auth-main"><div className="auth-mobile-brand"><Brand/></div><div className="auth-card"><span className="eyebrow">YOUR NEXT CHAPTER STARTS HERE</span><h2>{signup ? 'Make room for good work.' : 'Welcome back.'}</h2><p className="muted">{signup ? 'Create your account and bring everything together.' : 'Sign in to your Foundry workspace.'}</p>{error && <div role="alert" className="alert">{error}</div>}<form className="auth-form" onSubmit={async e => {
      e.preventDefault(); setBusy(true); setError('');
      const form = Object.fromEntries(new FormData(e.currentTarget));
      try { await request(`/api/auth/${signup ? 'signup' : 'login'}`, 'POST', form); await auth(); if (route !== '/join') navigate('/overview'); }
      catch (e: any) { setError(e.message); } finally { setBusy(false); }
    }}>{signup && <label>Name<input name="name" required autoComplete="name" placeholder="Alex Morgan"/></label>}<label>Email<input name="email" type="email" required autoComplete="email" placeholder="you@example.invalid"/></label><label>Password<input name="password" type="password" minLength={signup ? 12 : undefined} required autoComplete={signup ? 'new-password' : 'current-password'} placeholder={signup ? 'At least 12 characters' : 'Your password'}/></label><button className="button primary" disabled={busy}>{busy ? 'Opening workspace...' : signup ? 'Create account' : 'Sign in'}<Icon name="arrow" size={18}/></button></form><p className="auth-switch">{signup ? 'Already have an account?' : 'New to Foundry?'} <a href={signup ? '/signin' : '/signup'} onClick={e => { e.preventDefault(); navigate(signup ? '/signin' : '/signup'); }}>{signup ? 'Sign in' : 'Create an account'}</a></p><div className="local-note"><span className="live-dot"/>Local-first prototype. No external services.</div></div></main></div>;
  }

  function overview() {
    const cards = [{ name: 'Revenue', value: money(summary.revenueCents), icon: 'Invoices', sub: 'From paid invoices', accent: true }, { name: 'Unpaid invoices', value: money(summary.unpaidCents), icon: 'clock', sub: 'Draft and sent invoices' }, { name: 'Open orders', value: summary.openOrders || 0, icon: 'Orders', sub: `${summary.fulfilledOrders || 0} fulfilled to date` }, { name: 'Low stock', value: summary.lowStockProducts || 0, icon: 'Inventory', sub: 'Products with 5 or fewer units' }, { name: 'Open tasks', value: summary.openTasks || 0, icon: 'Projects', sub: `${summary.completedTasks || 0} completed tasks` }, { name: 'Customers', value: summary.customers || 0, icon: 'Customers', sub: 'Relationships in your workspace' }];
    const invoiceList: Row[] = data.invoices || [], total = invoiceList.length;
    const counts = ['draft', 'sent', 'paid', 'void'].map(s => invoiceList.filter(i => i.status === s).length);
    const totalTasks = (summary.openTasks || 0) + (summary.completedTasks || 0), completion = totalTasks ? Math.round(summary.completedTasks / totalTasks * 100) : 0;
    return <><div className="welcome-banner"><div><span className="eyebrow">THE BIG PICTURE</span><h2>Everything in its right place.</h2><p>A little clarity for the work ahead. Here’s where things stand.</p></div><div className="banner-art" aria-hidden="true"><div/><div/><div/><span><Icon name="check" size={26}/></span></div></div><div className="stats-grid">{cards.map(c => <section aria-label={c.name} className={`stat-card ${c.accent ? 'accent' : ''}`} key={c.name}><div className="stat-top"><span>{c.name}</span><Icon name={c.icon} size={19}/></div><strong>{c.value}</strong><span className="stat-sub">{c.sub}</span></section>)}</div><div className="overview-grid"><section className="panel"><div className="panel-head"><div><h3>Invoice pipeline</h3><p>A clear view of your billing</p></div><span className="subtle-tag">All time</span></div><div className="pipeline"><div className="pipeline-total"><strong>{total}</strong><span>total invoices</span></div><div className="stacked-chart" aria-label={`${counts[0]} draft, ${counts[1]} sent, ${counts[2]} paid, ${counts[3]} void invoices`}>{total ? counts.map((n, i) => n > 0 && <div key={i} className={`segment segment-${i}`} style={{ flex: n }} title={`${label(['draft', 'sent', 'paid', 'void'][i])}: ${n}`}/>) : <div className="segment-empty"/>}</div><div className="chart-legend">{['Draft', 'Sent', 'Paid', 'Void'].map((s, i) => <div key={s}><span className={`legend-dot segment-${i}`}/><span>{s}</span><strong>{counts[i]}</strong></div>)}</div>{!total && <p className="small muted">Your first invoice starts with a fulfilled order.</p>}</div><div className="panel-bottom"><span>From order to paid. All connected.</span><button className="text-button" onClick={() => navigate('/invoices')}>View invoices<Icon name="arrow" size={15}/></button></div></section><section className="panel progress-panel"><div className="panel-head"><div><h3>Work in motion</h3><p>Small steps. Real progress.</p></div><Icon name="Projects"/></div><div className="progress-ring" style={{ background: `conic-gradient(#427b67 ${completion}%, #edf0e9 0)` }}><div><strong>{completion}%</strong><span>complete</span></div></div><div className="task-counts"><span><strong>{summary.openTasks || 0}</strong>open tasks</span><span><strong>{summary.completedTasks || 0}</strong>completed</span></div><div className="panel-bottom"><span>{data.projects?.length || 0} projects, one workspace</span><button className="text-button" onClick={() => navigate('/projects')}>View projects<Icon name="arrow" size={15}/></button></div></section></div><section className="panel"><div className="panel-head"><div><h3>Latest activity</h3><p>The latest moves across your workspace</p></div><button className="text-button" onClick={() => navigate('/activity')}>All activity<Icon name="arrow" size={15}/></button></div>{data.activity?.length ? <ActivityList rows={data.activity.slice(0, 4)}/> : <div className="inline-empty">A fresh start. Your workspace activity will appear here.</div>}</section></>;
  }
  function customers() {
    const rows = (data.customers || []).filter((c: Row) => `${c.name} ${c.email} ${c.company}`.toLowerCase().includes(search.toLowerCase()));
    return <><div className="toolbar">{searchBox('Search customers')}<div className="toolbar-actions">{exportLink('customers')}{write && <button className="button secondary" onClick={() => open('import')}>Import customers</button>}</div></div><div className="panel table-panel"><div className="table-caption"><h3>All customers <span className="count">{rows.length}</span></h3><span className="muted small">Good relationships start here</span></div>{rows.length ? <div className="table-scroll"><table><thead><tr><th>Customer</th><th>Company</th><th>Email</th><th>Added</th><th>Actions</th></tr></thead><tbody>{rows.map((c: Row) => <tr key={c.id}><td><div className="person"><span className="avatar">{initials(c.name)}</span><strong>{c.name}</strong></div></td><td>{c.company || <span className="muted">Not set</span>}</td><td>{c.email || <span className="muted">Not set</span>}</td><td className="muted nowrap">{date(c.createdAt)}</td><td>{rowActions('customer', c, c.name)}</td></tr>)}</tbody></table></div> : <Empty icon="Customers" title={search ? 'No matching customers' : 'Meet your next great relationship'}>{search ? 'Try a different name, email or company.' : 'Add a customer or import your contacts to get things moving.'}</Empty>}</div></>;
  }
  function inventory() {
    const rows = (data.products || []).filter((p: Row) => `${p.name} ${p.sku} ${p.description}`.toLowerCase().includes(search.toLowerCase()));
    return <><div className="mini-metrics"><div><span>Catalog products</span><strong>{data.products?.length || 0}</strong></div><div><span>Units on hand</span><strong>{(data.products || []).reduce((s: number, p: Row) => s + p.stock, 0).toLocaleString()}</strong></div><div><span>Need attention</span><strong>{summary.lowStockProducts || 0}<small> low stock</small></strong></div></div><div className="toolbar">{searchBox('Search products')}{exportLink('products')}</div><div className="panel table-panel"><div className="table-caption"><h3>Product catalog <span className="count">{rows.length}</span></h3><span className="muted small">Every unit, accounted for</span></div>{rows.length ? <div className="table-scroll"><table><thead><tr><th>Product</th><th>SKU</th><th>Unit price</th><th>On hand</th><th>Actions</th></tr></thead><tbody>{rows.map((p: Row) => <tr key={p.id}><td><div className="person"><span className="product-icon"><Icon name="Inventory"/></span><div><strong>{p.name}</strong><span className="cell-sub">{p.description || 'No description'}</span></div></div></td><td><code>{p.sku}</code></td><td className="money">{money(p.priceCents)}</td><td><span className={`stock-amount ${p.stock <= 5 ? 'low' : ''}`}><span/>{p.stock}<small>{p.stock <= 5 ? 'Low stock' : 'In stock'}</small></span></td><td><div className="row-actions"><button className="text-button" aria-label={`Stock history ${p.sku}`} onClick={() => open('stock-history', p)}>History</button>{ops && <><button className="icon-button" aria-label={`Adjust stock ${p.sku}`} onClick={() => open('stock', p)}><Icon name="plus" size={17}/></button><button className="icon-button" aria-label={`Edit product ${p.sku}`} onClick={() => open('edit-product', p)}><Icon name="edit" size={16}/></button><button className="icon-button danger" aria-label={`Delete product ${p.sku}`} onClick={() => remove('products', p)}><Icon name="trash" size={16}/></button></>}</div></td></tr>)}</tbody></table></div> : <Empty icon="Inventory" title={search ? 'No matching products' : 'Build your product catalog'}>Add products, receive stock, and keep every order on track.</Empty>}</div></>;
  }
  function commerce(type: 'orders' | 'invoices') {
    const isOrder = type === 'orders', rows = (data[type] || []).filter((r: Row) => !status || r.status === status);
    return <><div className="toolbar"><label className="filter"><span>{isOrder ? 'Order' : 'Invoice'} status filter</span><select aria-label={`${isOrder ? 'Order' : 'Invoice'} status filter`} value={status} onChange={e => setStatus(e.target.value)}><option value="">All statuses</option>{(isOrder ? ['draft', 'fulfilled', 'cancelled'] : ['draft', 'sent', 'paid', 'void']).map(s => <option key={s} value={s}>{label(s)}</option>)}</select></label>{exportLink(type)}</div><div className="panel table-panel"><div className="table-caption"><h3>{isOrder ? 'Sales orders' : 'All invoices'} <span className="count">{rows.length}</span></h3><span className="muted small">{isOrder ? 'From request to ready' : 'A healthy business, down to the cent'}</span></div>{rows.length ? <div className="table-scroll"><table><thead><tr><th>{isOrder ? 'Order' : 'Invoice'}</th><th>Customer</th><th>Status</th><th>Date</th><th className="right">Total</th><th>Actions</th></tr></thead><tbody>{rows.map((r: Row) => <tr key={r.id}><td><strong className="record-number">{r.number}</strong></td><td>{isOrder ? customerName(r.customerId) : r.billTo.name}</td><td><Badge value={r.status}/></td><td className="muted nowrap">{date(r.createdAt)}</td><td className="money right">{money(r.totalCents)}</td><td><button className="text-button" aria-label={`Open ${isOrder ? 'order' : 'invoice'} ${r.number}`} onClick={() => open(isOrder ? 'order-details' : 'invoice-details', r)}>View<Icon name="arrow" size={14}/></button></td></tr>)}</tbody></table></div> : <Empty icon={isOrder ? 'Orders' : 'Invoices'} title={status ? 'Nothing in this status yet' : isOrder ? 'Great things start with an order' : 'Give your good work a number'}>{isOrder ? 'Connect customers and products, then fulfill with confidence.' : 'Fulfill an order, then create its invoice from the order details.'}</Empty>}</div></>;
  }
  function projects() {
    const project = lookup('projects', projectId || '');
    const tasks = (data.tasks || []).filter((t: Row) => (!projectId || t.projectId === projectId) && `${t.title} ${t.description}`.toLowerCase().includes(search.toLowerCase()) && (!status || t.status === status) && (!priority || t.priority === priority));
    return <>{!projectId ? <div className="project-grid">{(data.projects || []).map((p: Row) => { const pt = (data.tasks || []).filter((t: Row) => t.projectId === p.id), done = pt.filter((t: Row) => t.status === 'done').length; return <article className="project-card" key={p.id}><div className="project-card-top"><span className="project-symbol"><Icon name="Projects" size={25}/></span>{write && <div className="row-actions"><button className="icon-button" aria-label={`Edit project ${p.name}`} onClick={() => open('edit-project', p)}><Icon name="edit" size={16}/></button><button className="icon-button danger" aria-label={`Delete project ${p.name}`} onClick={() => remove('projects', p)}><Icon name="trash" size={16}/></button></div>}</div><h3>{p.name}</h3><p>{p.description || 'A fresh space to do your best work.'}</p><div className="project-progress"><span style={{ width: `${pt.length ? done / pt.length * 100 : 0}%` }}/></div><div className="project-card-bottom"><span>{done} / {pt.length} tasks done</span><button className="text-button" aria-label={`Open project ${p.name}`} onClick={() => { setProjectId(p.id); setSearch(''); setStatus(''); setPriority(''); }}>Open board<Icon name="arrow" size={15}/></button></div></article>; })}{!data.projects?.length && <div className="panel wide"><Empty icon="Projects" title="Make space for your next project">Bring tasks, teammates, and the details that matter into one place.</Empty></div>}</div> : <div className="board-heading"><div><button className="text-button" onClick={() => setProjectId(null)}>All projects</button><h2>{project?.name}</h2><p className="muted">{project?.description}</p></div>{write && addButton('New task', 'new-task')}</div>}
    {(projectId || data.tasks?.length > 0) && <><div className="toolbar task-toolbar">{searchBox('Search tasks')}<div className="toolbar-actions"><select aria-label="Status filter" value={status} onChange={e => setStatus(e.target.value)}><option value="">All statuses</option>{statuses(['todo', 'in_progress', 'done']).map(s => <option key={s.value} value={s.value}>{s.label}</option>)}</select><select aria-label="Priority filter" value={priority} onChange={e => setPriority(e.target.value)}><option value="">All priorities</option>{statuses(['low', 'medium', 'high']).map(s => <option key={s.value} value={s.value}>{s.label}</option>)}</select>{exportLink('tasks')}</div></div><div className="kanban">{['todo', 'in_progress', 'done'].map(s => <section className={`board-column ${s}`} aria-label={label(s)} key={s}><div className="column-head"><h3><span className="column-dot"/>{label(s)}<span className="count">{tasks.filter((t: Row) => t.status === s).length}</span></h3>{write && projectId && <button className="icon-button" aria-label={`Add ${label(s)} task`} onClick={() => open('new-task', { status: s })}><Icon name="plus" size={16}/></button>}</div>{tasks.filter((t: Row) => t.status === s).map((t: Row) => <article className="task-card" key={t.id}><div className="task-top"><Badge value={t.priority}/>{!projectId && <span className="small muted">{lookup('projects', t.projectId)?.name}</span>}</div><button className="task-title" aria-label={`Open task ${t.title}`} onClick={() => open('task-details', t)}>{t.title}</button>{t.description && <p>{t.description}</p>}<div className="task-bottom"><span className="small muted"><Icon name="clock" size={13}/>{t.dueDate ? date(t.dueDate) : 'No due date'}</span><div className="row-actions">{t.assigneeId && <span className="avatar tiny" title={(data.members || []).find((m: Row) => m.userId === t.assigneeId)?.name}>{initials((data.members || []).find((m: Row) => m.userId === t.assigneeId)?.name)}</span>}{write && <><button className="icon-button" aria-label={`Edit task ${t.title}`} onClick={() => open('edit-task', t)}><Icon name="edit" size={14}/></button><button className="icon-button danger" aria-label={`Delete task ${t.title}`} onClick={() => remove('tasks', t)}><Icon name="trash" size={14}/></button></>}</div></div></article>)}{!tasks.some((t: Row) => t.status === s) && <div className="board-empty">A little room for what’s next.</div>}</section>)}</div></>}
    </>;
  }
  function team() { return <><div className="team-banner"><span className="project-symbol"><Icon name="Team" size={27}/></span><div><h3>Better, together.</h3><p>Give everyone the right space to contribute. Invitations stay local.</p></div><a className="button secondary" href="/join" onClick={e => { e.preventDefault(); navigate('/join'); }}>Join with a token<Icon name="arrow" size={15}/></a></div><div className="panel table-panel"><div className="table-caption"><h3>Workspace members <span className="count">{data.members?.length || 0}</span></h3><span className="muted small">{workspace?.name}</span></div><div className="table-scroll"><table><thead><tr><th>Member</th><th>Email</th><th>Role</th>{owner && <th>Manage access</th>}</tr></thead><tbody>{(data.members || []).map((m: Row) => <tr key={m.userId}><td><div className="person"><span className="avatar">{initials(m.name)}</span><strong>{m.name}{m.userId === me?.user.id && <span className="you">you</span>}</strong></div></td><td>{m.email}</td><td><Badge value={m.role}/></td>{owner && <td>{m.role !== 'owner' ? <MemberActions key={`${m.userId}-${m.role}`} member={m} busy={busy} save={(r: string) => action(() => api(`/members/${m.userId}`, 'PATCH', { role: r }), 'Member role updated.')} remove={() => { if (confirm(`Remove ${m.email} from this workspace?`)) action(() => api(`/members/${m.userId}`, 'DELETE'), 'Member removed.'); }}/> : <span className="muted small">Original workspace owner</span>}</td>}</tr>)}</tbody></table></div></div><div className="permission-note"><Icon name="Team"/><p><strong>A role for every kind of work.</strong> Managers run operations. Members collaborate on customers and projects. Read only members can view and export.</p></div></>; }
  function modalContent() {
    if (!modal) return null;
    const item = modal.item || {}, kind = modal.kind;
    const current = kind === 'order-details' ? lookup('orders', item.id) || item : kind === 'invoice-details' ? lookup('invoices', item.id) || item : kind === 'task-details' ? lookup('tasks', item.id) || item : kind === 'customer-details' ? lookup('customers', item.id) || item : item;
    const titles: Record<string, string> = { 'new-workspace': 'New workspace', 'new-customer': 'New customer', 'edit-customer': 'Edit customer', 'customer-details': 'Customer details', import: 'Import customers', 'new-product': 'New product', 'edit-product': 'Edit product', stock: 'Adjust stock', 'stock-history': 'Stock history', 'new-order': 'New order', 'edit-order': 'Edit order', 'order-details': 'Order details', 'invoice-details': 'Invoice details', 'new-project': 'New project', 'edit-project': 'Edit project', 'new-task': 'New task', 'edit-task': 'Edit task', 'task-details': 'Task details', invite: 'Invite member' };
    let content: React.ReactNode;
    if (kind === 'new-workspace') content = <Form busy={busy} fields={[{ name: 'name', label: 'Workspace name', required: true }]} submit="Create workspace" onSubmit={v => action(async () => { await request('/api/workspaces', 'POST', v); await auth(); navigate('/overview'); }, 'Workspace created.')}/>;
    else if (kind.endsWith('customer') && kind !== 'import') content = <Form fields={customerFields(kind === 'edit-customer' ? item : undefined)} busy={busy} submit={kind === 'edit-customer' ? 'Save changes' : 'Create customer'} onSubmit={v => action(() => api(`/customers${kind === 'edit-customer' ? '/' + item.id : ''}`, kind === 'edit-customer' ? 'PATCH' : 'POST', v), 'Customer saved.')}/>;
    else if (kind === 'import') content = <><p className="muted">Upload up to 200 customers. All rows are validated before anything is saved.</p><div className="csv-hint"><Icon name="file"/><code>name,email,company,notes</code></div><form className="form" onSubmit={e => { e.preventDefault(); const f = new FormData(e.currentTarget).get('csv') as File; action(async () => api('/import/customers', 'POST', { csv: await f.text() }), 'Customers imported.'); }}><label>CSV file<input type="file" name="csv" accept=".csv,text/csv" required/></label><div className="form-footer"><span className="small muted">CSV, maximum 1 MB</span><button className="button primary" disabled={busy}>Import CSV</button></div></form></>;
    else if (kind.endsWith('product')) content = <Form busy={busy} fields={productFields(kind === 'edit-product' ? item : undefined)} submit={kind === 'edit-product' ? 'Save changes' : 'Create product'} onSubmit={v => action(async () => { if (!/^\d+(\.\d{1,2})?$/.test(v.price)) throw new Error('Enter a positive dollar amount with at most two decimal places.'); const [d, c = ''] = v.price.split('.'); const { price, ...rest } = v; return api(`/products${kind === 'edit-product' ? '/' + item.id : ''}`, kind === 'edit-product' ? 'PATCH' : 'POST', { ...rest, priceCents: Number(d) * 100 + Number(c.padEnd(2, '0')) }); }, 'Product saved.')}/>;
    else if (kind === 'stock') content = <><div className="detail-summary"><div><strong>{item.name}</strong><span>{item.sku}</span></div><div><span>Current stock</span><strong>{lookup('products', item.id)?.stock ?? item.stock} units</strong></div></div><Form busy={busy} fields={[{ name: 'delta', label: 'Quantity change', type: 'number', step: '1', required: true }, { name: 'reason', label: 'Reason', required: true }]} submit="Save stock change" onSubmit={v => action(() => api('/stock-movements', 'POST', { ...v, delta: Number(v.delta), productId: item.id }), 'Stock updated.')}/></>;
    else if (kind === 'stock-history') content = <StockHistory item={item} api={api} version={version}/>;
    else if (kind === 'new-order' || kind === 'edit-order') content = <OrderForm customers={data.customers || []} products={data.products || []} item={kind === 'edit-order' ? item : undefined} busy={busy} save={v => action(() => api('/orders' + (kind === 'edit-order' ? '/' + item.id : ''), kind === 'edit-order' ? 'PATCH' : 'POST', v), 'Order saved.')}/>;
    else if (kind === 'order-details') content = <><div className="detail-summary"><div><span>Sales order</span><strong>{current.number}</strong><span>{customerName(current.customerId)}</span></div><Badge value={current.status}/></div><LineItems item={current}/>{ops && <div className="detail-actions">{current.status === 'draft' && <><button className="button primary" disabled={busy} onClick={() => action(() => api(`/orders/${current.id}/fulfill`, 'POST', { idempotencyKey: `ui-${current.id}` }), 'Order fulfilled.', true)}><Icon name="check" size={16}/>Fulfill order</button><button className="button secondary" onClick={() => open('edit-order', current)}>Edit order</button><button className="button secondary" disabled={busy} onClick={() => action(() => api(`/orders/${current.id}/cancel`, 'POST', {}), 'Order cancelled.', true)}>Cancel order</button><button className="button danger-button" onClick={() => remove('orders', current)}>Delete order</button></>}{current.status === 'fulfilled' && !(data.invoices || []).some((i: Row) => i.orderId === current.id) && <button className="button primary" disabled={busy} onClick={() => action(() => api('/invoices', 'POST', { orderId: current.id }), 'Invoice created. Find it in Invoices.', true)}>Create invoice<Icon name="arrow" size={16}/></button>}</div>}<Attachments entityType="order" entityId={current.id} api={api} wid={wid} write={write} ops={ops} userId={me?.user.id} version={version} action={action}/></>;
    else if (kind === 'invoice-details') content = <><div className="invoice-brand"><Brand/><span>INVOICE</span></div><div className="detail-summary"><div><span>Bill to</span><strong>{current.billTo.name}</strong><span>{current.billTo.company}</span><span>{current.billTo.email}</span></div><div><strong>{current.number}</strong><Badge value={current.status}/><span>Issued {date(current.createdAt)}</span></div></div><LineItems item={current}/><p className="small muted">USD. No tax or discount. Bill-to and line items are immutable snapshots.</p>{current.paidAt && <div className="paid-note"><Icon name="check" size={16}/>Paid {date(current.paidAt)}. Recorded locally.</div>}{ops && <div className="detail-actions">{current.status === 'draft' && <button className="button primary" disabled={busy} onClick={() => action(() => api(`/invoices/${current.id}`, 'PATCH', { status: 'sent' }), 'Invoice marked sent.', true)}>Mark sent</button>}{current.status === 'sent' && <button className="button primary" disabled={busy} onClick={() => action(() => api(`/invoices/${current.id}`, 'PATCH', { status: 'paid' }), 'Invoice marked paid.', true)}>Mark paid</button>}{['draft', 'sent'].includes(current.status) && <button className="button secondary" disabled={busy} onClick={() => action(() => api(`/invoices/${current.id}`, 'PATCH', { status: 'void' }), 'Invoice voided.', true)}>Void invoice</button>}</div>}</>;
    else if (kind.endsWith('project')) content = <Form fields={[{ name: 'name', label: 'Project name', required: true, value: item.name }, { name: 'description', label: 'Description', type: 'textarea', value: item.description }]} busy={busy} submit={kind === 'edit-project' ? 'Save changes' : 'Create project'} onSubmit={v => action(() => api('/projects' + (kind === 'edit-project' ? '/' + item.id : ''), kind === 'edit-project' ? 'PATCH' : 'POST', v), 'Project saved.')}/>;
    else if (kind === 'new-task' || kind === 'edit-task') content = <Form fields={taskFields(item)} busy={busy} submit={kind === 'edit-task' ? 'Save changes' : 'Create task'} onSubmit={v => action(() => api(kind === 'edit-task' ? '/tasks/' + item.id : '/projects/' + projectId + '/tasks', kind === 'edit-task' ? 'PATCH' : 'POST', { ...v, assigneeId: v.assigneeId || null, dueDate: v.dueDate || null }), 'Task saved.')}/>;
    else if (kind === 'customer-details') content = <><div className="customer-profile"><span className="avatar large">{initials(current.name)}</span><div><h3>{current.name}</h3><p>{current.company || 'No company'}</p><p>{current.email || 'No email'}</p></div>{write && <button className="button secondary" onClick={() => open('edit-customer', current)}>Edit customer</button>}</div><div className="notes-box"><span className="eyebrow">NOTES</span><p>{current.notes || 'No notes yet.'}</p></div><Attachments entityType="customer" entityId={current.id} api={api} wid={wid} write={write} ops={ops} userId={me?.user.id} version={version} action={action}/></>;
    else if (kind === 'task-details') content = <><div className="detail-summary"><div><span>{lookup('projects', current.projectId)?.name}</span><h3>{current.title}</h3><span>{date(current.dueDate)}</span></div><div><Badge value={current.status}/><Badge value={current.priority}/></div></div><p className="user-text">{current.description || 'No description yet.'}</p>{write && <button className="button secondary" onClick={() => open('edit-task', current)}><Icon name="edit" size={15}/>Edit task</button>}<Comments taskId={current.id} api={api} write={write} ops={ops} userId={me?.user.id} action={action} version={version}/><Attachments entityType="task" entityId={current.id} api={api} wid={wid} write={write} ops={ops} userId={me?.user.id} version={version} action={action}/></>;
    else if (kind === 'invite') content = modal.token ? <div className="invite-success"><span className="success-symbol"><Icon name="check" size={28}/></span><h3>An open door for your teammate.</h3><p>Share this local token with the invited person. They can accept it on the Join workspace page. It expires in 7 days and works once.</p><label>Invite token<input readOnly value={modal.token} onFocus={e => e.target.select()}/></label><button className="button primary" onClick={close}>Done</button></div> : <Form fields={[{ name: 'email', label: 'Email', type: 'email', required: true }, { name: 'role', label: 'Role', options: statuses(['manager', 'member', 'read_only']), value: 'member' }]} busy={busy} submit="Create invite" onSubmit={async v => { const result = await action(() => api('/invites', 'POST', v), 'Invite created. No email was sent.', true); if (result) setModal({ kind: 'invite', token: result.invite.token }); }}/>;
    return <Dialog key={`${kind}-${item.id || ''}`} name={titles[kind] || 'Details'} close={close} error={error}>{content}</Dialog>;
  }

  return <div className="app-shell"><aside className={`sidebar ${mobile ? 'mobile-open' : ''}`}><div className="sidebar-top"><Brand/><button className="icon-button mobile-close" aria-label="Close navigation" onClick={() => setMobile(false)}><Icon name="close"/></button></div><div className="workspace-control"><span className="workspace-icon">{initials(workspace?.name)}</span><label><span>YOUR WORKSPACE</span><select aria-label="Workspace" value={wid || ''} onChange={e => { const next = e.target.value; setError(''); request(`/api/workspaces/${next}/select`, 'POST', {}).then(auth).catch(e => setError(e.message)); setProjectId(null); }}>{(me.workspaces || []).map((w: Row) => <option key={w.id} value={w.id}>{w.name}</option>)}</select></label></div><span className="nav-caption">WORKSPACE</span><nav>{names.map((n, i) => <React.Fragment key={n}>{i === 6 && <div className="nav-divider"/>}<a href={'/' + n.toLowerCase()} className={page === n ? 'active' : ''} onClick={e => { e.preventDefault(); navigate('/' + n.toLowerCase()); }}><Icon name={n}/><span>{n}</span>{n === 'Orders' && summary.openOrders > 0 && <span className="nav-count" aria-hidden="true">{summary.openOrders}</span>}{n === 'Projects' && summary.openTasks > 0 && <span className="nav-count" aria-hidden="true">{summary.openTasks}</span>}</a></React.Fragment>)}</nav><div className="sidebar-bottom"><button className="new-workspace" onClick={() => open('new-workspace')}><Icon name="plus" size={17}/>New workspace</button><div className="sidebar-note"><div className="sidebar-note-symbol">✳</div><strong>Built for the way you work.</strong><span>Everything connected.<br/>Nothing in the way.</span></div><div className="user-menu"><span className="avatar dark">{initials(me.user.name)}</span><div><strong>{me.user.name}</strong><span>{label(role || 'member')}</span></div><button className="icon-button" aria-label="Sign out" title="Sign out" onClick={() => action(async () => { await request('/api/auth/logout', 'POST', {}); generation.current++; setMe(null); setData({}); navigate('/signin'); }, 'Signed out.')}><Icon name="logout" size={19}/></button></div></div></aside>{mobile && <button className="nav-scrim" aria-label="Close navigation backdrop" onClick={() => setMobile(false)}/>}
    <div className="main-shell"><header className="topbar"><div><button className="icon-button nav-toggle" aria-label="Open navigation" onClick={() => setMobile(true)}><Icon name="menu"/></button><span className="breadcrumb">Workspace <span>/</span> <strong>{page}</strong></span></div><div className="topbar-right"><span className="live-status"><span className="live-dot"/>{loading ? 'Connecting' : 'Live workspace'}</span><span className="topbar-divider"/><span className="topbar-date">{new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}</span><span className="avatar tiny">{initials(me.user.name)}</span></div></header><main className="main-content"><div className="page-heading"><div><div className="eyebrow">{page === 'Overview' ? `WELCOME BACK, ${me.user.name.split(' ')[0].toUpperCase()}` : 'YOUR CONNECTED WORKSPACE'}</div><h1>{page === 'Overview' ? 'Workspace overview' : page}</h1><p>{({ Overview: 'A good day starts with a clear picture.', Customers: 'Real relationships. Every detail in one place.', Inventory: 'Know what you have. Be ready for what’s next.', Orders: 'Keep your business moving, one order at a time.', Invoices: 'Good work deserves a clear paper trail.', Projects: 'Turn the work ahead into work well done.', Activity: 'Every meaningful move, in one place.', Team: 'The right people. The right access.', 'Join workspace': 'A new connection is one token away.' } as Row)[page]}</p></div><div className="heading-actions">{page === 'Overview' && write && <button className="button primary" onClick={() => open('new-customer')}><Icon name="plus" size={17}/>New customer</button>}{page === 'Customers' && write && addButton('New customer', 'new-customer')}{page === 'Inventory' && ops && addButton('New product', 'new-product')}{page === 'Orders' && ops && addButton('New order', 'new-order')}{page === 'Projects' && write && addButton('New project', 'new-project')}{page === 'Team' && owner && addButton('Invite member', 'invite')}</div></div>{error && !modal && <div className="alert" role="alert">{error}<button className="icon-button" aria-label="Dismiss error" onClick={() => setError('')}><Icon name="close" size={16}/></button></div>}{loading ? <div className="loading-panel"><span className="spinner"/>Bringing your workspace together...</div> : page === 'Overview' ? overview() : page === 'Customers' ? customers() : page === 'Inventory' ? inventory() : page === 'Orders' ? commerce('orders') : page === 'Invoices' ? commerce('invoices') : page === 'Projects' ? projects() : page === 'Team' ? team() : page === 'Activity' ? <div className="panel"><div className="panel-head"><div><h3>Workspace journal</h3><p>Real changes, with the people behind them</p></div><span className="subtle-tag">Latest 50 events</span></div>{data.activity?.length ? <ActivityList rows={data.activity}/> : <Empty icon="Activity" title="Your story starts here">Customer updates, stock changes, and project progress will appear as they happen.</Empty>}</div> : <div className="panel join-panel"><span className="project-symbol"><Icon name="Team" size={28}/></span><h2>A seat at the table.</h2><p className="muted">Paste the token shared by your workspace owner. It must match your signed-in email.</p><Form fields={[{ name: 'token', label: 'Invite token', required: true }]} busy={busy} submit="Join workspace" onSubmit={v => action(async () => { await request('/api/invites/accept', 'POST', v); await auth(); navigate('/overview'); }, 'Welcome to your new workspace.')}/></div>}<footer className="page-footer"><span>Foundry <span className="footer-dot">/</span> Business operations, together.</span><span>LOCAL WORKSPACE</span></footer></main></div>{notice && <div className="toast" role="status"><Icon name="check" size={18}/>{notice}</div>}{modalContent()}</div>;
}

function ActivityList({ rows }: { rows: Row[] }) { return <div className="activity-list">{rows.map(r => <div className="activity-row" key={r.id}><span className="activity-icon"><Icon name={r.entityType === 'customer' ? 'Customers' : r.entityType === 'product' ? 'Inventory' : r.entityType === 'order' ? 'Orders' : r.entityType === 'invoice' ? 'Invoices' : r.entityType === 'task' || r.entityType === 'project' ? 'Projects' : 'Activity'} size={17}/></span><div><p><strong>{r.actorName}</strong> {r.action === 'stock.adjusted' ? 'adjusted inventory stock' : r.action === 'member.joined' ? 'joined the workspace' : `${r.action.split('.')[1]} ${['attachment', 'order', 'invoice', 'invite'].includes(r.entityType) ? 'an' : 'a'} ${r.entityType}`}</p><span>{label(r.entityType)} update</span></div><time dateTime={r.createdAt}>{date(r.createdAt)} <span>{new Date(r.createdAt).toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' })}</span></time></div>)}</div>; }
function LineItems({ item }: { item: Row }) { return <div className="line-items"><div className="table-scroll"><table><thead><tr><th>Item</th><th>Qty</th><th>Unit price</th><th className="right">Amount</th></tr></thead><tbody>{item.items.map((i: Row) => <tr key={i.productId}><td><strong>{i.name}</strong><span className="cell-sub">{i.sku}</span></td><td>{i.quantity}</td><td>{money(i.unitPriceCents)}</td><td className="right money">{money(i.lineTotalCents)}</td></tr>)}</tbody></table></div><div className="total-line"><span>Total <small>USD</small></span><strong>{money(item.totalCents)}</strong></div></div>; }
function MemberActions({ member, busy, save, remove }: { member: Row; busy: boolean; save: (r: string) => void; remove: () => void }) { const [role, setRole] = useState(member.role); return <div className="row-actions"><select aria-label={`Role for ${member.email}`} value={role} onChange={e => setRole(e.target.value)}>{statuses(['manager', 'member', 'read_only']).map(r => <option key={r.value} value={r.value}>{r.label}</option>)}</select><button className="button small-button secondary" disabled={busy} aria-label={`Save role for ${member.email}`} onClick={() => save(role)}>Save role</button><button className="icon-button danger" aria-label={`Remove member ${member.email}`} disabled={busy} onClick={remove}><Icon name="trash" size={16}/></button></div>; }
function OrderForm({ customers, products, item, save, busy }: { customers: Row[]; products: Row[]; item?: Row; save: (v: Row) => void; busy: boolean }) {
  const [customer, setCustomer] = useState(item?.customerId || customers[0]?.id || ''), [product, setProduct] = useState(products[0]?.id || ''), [quantity, setQuantity] = useState('1');
  const [lines, setLines] = useState<Row[]>(item?.items || []), [error, setError] = useState('');
  const total = lines.reduce((s, l) => s + l.unitPriceCents * l.quantity, 0);
  return <form className="form" onSubmit={e => { e.preventDefault(); if (!lines.length) { setError('Add at least one product line.'); return; } save({ customerId: customer, items: lines.map(l => ({ productId: l.productId, quantity: l.quantity })) }); }}>
    {error && <div className="alert" role="alert">{error}</div>}{(!customers.length || !products.length) && <div className="info-box">Add a customer and a product before creating an order.</div>}
    <label>Customer<select aria-label="Customer" value={customer} onChange={e => setCustomer(e.target.value)} required>{!customers.length && <option value="">No customers yet</option>}{customers.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}</select></label>
    <div className="line-editor"><label>Product<select aria-label="Product" value={product} onChange={e => setProduct(e.target.value)}>{!products.length && <option value="">No products yet</option>}{products.map(p => <option key={p.id} value={p.id}>{p.sku} — {p.name}</option>)}</select></label><label>Quantity<input aria-label="Quantity" type="number" value={quantity} min="1" max="10000" step="1" onChange={e => setQuantity(e.target.value)}/></label><button type="button" className="button secondary" onClick={() => { const p = products.find(p => p.id === product), q = Number(quantity); if (!p || !Number.isInteger(q) || q < 1 || q > 10000) { setError('Choose a product and a whole quantity from 1 to 10,000.'); return; } if (lines.some(l => l.productId === p.id)) { setError('This product is already in the order. Remove its line to change the quantity.'); return; } setError(''); setLines([...lines, { productId: p.id, sku: p.sku, name: p.name, unitPriceCents: p.priceCents, quantity: q }]); }}><Icon name="plus" size={15}/>Add line</button></div>
    <div className="order-lines">{lines.length ? lines.map(l => <div key={l.productId}><span><strong>{l.name}</strong><small>{l.sku} · {l.quantity} × {money(l.unitPriceCents)}</small></span><strong>{money(l.unitPriceCents * l.quantity)}</strong><button type="button" className="icon-button" aria-label={`Remove line ${l.sku}`} onClick={() => setLines(lines.filter(i => i.productId !== l.productId))}><Icon name="close" size={15}/></button></div>) : <p className="muted small">Your order lines will appear here.</p>}</div>
    <div className="total-line"><span>Order total</span><strong>{money(total)}</strong></div><div className="form-footer"><span className="muted small">Stock is reserved only on fulfillment.</span><button className="button primary" disabled={busy || !customers.length || !products.length}>{item ? 'Save changes' : 'Create order'}</button></div></form>;
}
function StockHistory({ item, api, version }: { item: Row; api: (p: string) => Promise<any>; version: number }) {
  const [rows, setRows] = useState<Row[] | null>(null), [error, setError] = useState('');
  useEffect(() => { let alive = true; api(`/stock-movements?productId=${item.id}`).then(r => { if (alive) setRows(r.movements); }).catch(e => { if (alive) setError(e.message); }); return () => { alive = false; }; }, [item.id, version]);
  return <><h3>{item.sku} · {item.name}</h3><p className="muted">A permanent record of every stock change.</p>{error && <div className="alert" role="alert">{error}</div>}{rows?.length ? <div className="history-list">{rows.map(r => <div key={r.id}><span className={r.delta > 0 ? 'delta positive' : 'delta'}>{r.delta > 0 ? '+' : ''}{r.delta}</span><div><strong>{r.reason}</strong><span>{label(r.kind)} · {date(r.createdAt)}</span></div></div>)}</div> : <p className="inline-empty">{rows ? 'No stock movements yet.' : 'Loading history...'}</p>}</>;
}
type DetailProps = { api: (p: string, method?: string, b?: any) => Promise<any>; write: boolean; ops: boolean; userId: string; version: number; action: (fn: () => Promise<any>, success: string, keep?: boolean) => Promise<any> };
function Attachments({ entityType, entityId, api, wid, write, ops, userId, version, action }: DetailProps & { entityType: string; entityId: string; wid: string }) {
  const [rows, setRows] = useState<Row[]>([]), [error, setError] = useState(''), [busy, setBusy] = useState(false); const input = useRef<HTMLInputElement>(null);
  useEffect(() => { let alive = true; api(`/attachments?entityType=${entityType}&entityId=${entityId}`).then(r => { if (alive) setRows(r.attachments); }).catch(e => { if (alive) setError(e.message); }); return () => { alive = false; }; }, [entityType, entityId, version]);
  return <section className="detail-section"><h3><Icon name="file" size={18}/>Attachments<span className="count">{rows.length}</span></h3>{error && <div role="alert" className="alert">{error}</div>}<div className="attachment-list">{rows.map(a => <div key={a.id}><Icon name="file" size={20}/><a href={`/api/w/${wid}/attachments/${a.id}/download`} aria-label={`Download attachment ${a.fileName}`}>{a.fileName}<span>{(a.size / 1024).toFixed(1)} KB</span></a>{write && (ops || a.createdBy === userId) && <button className="icon-button danger" aria-label={`Delete attachment ${a.fileName}`} onClick={() => { if (confirm(`Delete ${a.fileName}?`)) action(() => api('/attachments/' + a.id, 'DELETE'), 'Attachment deleted.', true); }}><Icon name="trash" size={16}/></button>}</div>)}</div>{write && <form className="upload-form" onSubmit={async e => { e.preventDefault(); const file = input.current?.files?.[0]; if (!file) { setError('Choose an attachment first.'); return; } setBusy(true); setError(''); const form = new FormData(); form.set('file', file); form.set('entityType', entityType); form.set('entityId', entityId); const result = await action(() => api('/attachments', 'POST', form), 'Attachment uploaded.', true); if (result && input.current) input.current.value = ''; setBusy(false); }}><label>Attachment<input ref={input} type="file" accept=".txt,.md,.csv,.pdf,.png,.jpg,.jpeg"/></label><button className="button secondary" disabled={busy}>Upload attachment</button><span className="small muted">TXT, MD, CSV, PDF, PNG or JPEG. Up to 2 MiB.</span></form>}{!write && !rows.length && <p className="muted small">No attachments yet.</p>}</section>;
}
function Comments({ taskId, api, write, ops, userId, action, version }: DetailProps & { taskId: string }) {
  const [rows, setRows] = useState<Row[]>([]), [body, setBody] = useState(''), [error, setError] = useState(''), [busy, setBusy] = useState(false);
  useEffect(() => { let alive = true; api(`/tasks/${taskId}/comments`).then(r => { if (alive) setRows(r.comments); }).catch(e => { if (alive) setError(e.message); }); return () => { alive = false; }; }, [taskId, version]);
  return <section className="detail-section"><h3>Conversation<span className="count">{rows.length}</span></h3>{error && <div role="alert" className="alert">{error}</div>}{rows.map(c => <div className="comment" key={c.id}><span className="avatar tiny">{initials(c.author.name)}</span><div><strong>{c.author.name}</strong><span className="small muted">{date(c.createdAt)}</span><p>{c.body}</p></div>{write && (ops || c.author.id === userId) && <button className="icon-button danger" aria-label={`Delete comment by ${c.author.name}`} onClick={() => { if (confirm('Delete this comment?')) action(() => api('/comments/' + c.id, 'DELETE'), 'Comment deleted.', true); }}><Icon name="trash" size={14}/></button>}</div>)}{!rows.length && <p className="small muted">A good conversation starts with a comment.</p>}{write && <form className="comment-form" onSubmit={async e => { e.preventDefault(); setBusy(true); const result = await action(() => api(`/tasks/${taskId}/comments`, 'POST', { body }), 'Comment added.', true); if (result) setBody(''); setBusy(false); }}><label>Comment<textarea rows={3} maxLength={2000} required value={body} onChange={e => setBody(e.target.value)} placeholder="Share a thought or an update..."/></label><button className="button primary" disabled={busy}>Add comment</button></form>}</section>;
}

createRoot(document.getElementById('root')!).render(<App/>);
